WITH expected(table_name, column_name) AS (VALUES ('memories','id'),('memories','content'),('memories','title'),('memories','subtitle'),('memories','type'),('memories','user_id'),('memories','index_id'),('memories','metadata'),('memories','embedding'),('memories','search_vector'),('memories','importance'),('memories','stability'),('memories','priority'),('memories','access_count'),('memories','last_accessed_at'),('memories','last_decay_at'),('memory_relationships','source_id'),('memory_relationships','target_id'),('memory_relationships','relation_type'),('memory_relationships','link_type'),('memory_relationships','confidence'),('memory_relationships','metadata'),('memory_usage_log','memory_id'),('memory_usage_log','event_type'),('memory_usage_log','session_context'),('url_tokens','name'),('url_tokens','token_hash'),('url_tokens','scopes')), missing AS (SELECT table_name, column_name FROM expected EXCEPT SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = 'public') SELECT COUNT(*) AS missing_expected_columns FROM missing;
